export class DashboardComponent {
  metrics: DashboardMetric[] = [
    { id: 1, title: 'Active Users', value: 1250, unit: 'users' },
    { id: 2, title: 'Revenue', value: 8500, unit: 'USD' },
    { id: 3, title: 'Response Time', value: 45, unit: 'ms' }
  ];

  updateMetrics() {
    this.metrics = this.metrics.map(metric => ({
      ...metric,
      value: metric.value + Math.floor(Math.random() * 100)
    }));
  }

  ngOnInit() {
